 jsonb:='{}'; hash_all text; t record;
BEGIN
 IF lf_ops.nucleo_param_valor_v1('AUTH.DNI_FORMAT_LENGTH') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='AUTH' AND config_key='DNI_FORMAT_LENGTH' AND hecho='as_dni_length') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT AUTH.DNI_FORMAT_LENGTH'; END IF;
 IF lf_ops.nucleo_param_valor_v1('AUTH.OTP_ORDINARY_RESEND_TIMER_SECONDS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='AUTH' AND config_key='OTP_ORDINARY_RESEND_TIMER_SECONDS' AND hecho='as_otp_resend_seconds') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT AUTH.OTP_ORDINARY_RESEND_TIMER_SECONDS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('AUTH.OTP_UI_SLOT_COUNT') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='AUTH' AND config_key='OTP_UI_SLOT_COUNT' AND hecho='as_otp_slots') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT AUTH.OTP_UI_SLOT_COUNT'; END IF;
 IF lf_ops.nucleo_param_valor_v1('UX.CTA_TOUCH_TARGET_MIN_PX') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='UX' AND config_key='CTA_TOUCH_TARGET_MIN_PX' AND hecho='as_cta_min_dimension_px') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT UX.CTA_TOUCH_TARGET_MIN_PX'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.DISPLAY_WHOLE_AMOUNT_DECIMALS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='DISPLAY_WHOLE_AMOUNT_DECIMALS' AND hecho='as_whole_amount_decimals') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT CLIENT.DISPLAY_WHOLE_AMOUNT_DECIMALS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.DISPLAY_INSTALLMENT_DECIMALS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='DISPLAY_INSTALLMENT_DECIMALS' AND hecho='as_installment_decimals') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT CLIENT.DISPLAY_INSTALLMENT_DECIMALS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('UX.HOME_VARIANT_MAX_SKELETON_SECONDS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='UX' AND config_key='HOME_VARIANT_MAX_SKELETON_SECONDS' AND hecho='as_home_wait_seconds') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT UX.HOME_VARIANT_MAX_SKELETON_SECONDS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('UX.CLARITY_NODE_MIN_TEXT_PX') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='UX' AND config_key='CLARITY_NODE_MIN_TEXT_PX' AND hecho='as_clarity_min_text_px') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT UX.CLARITY_NODE_MIN_TEXT_PX'; END IF;
 IF lf_ops.nucleo_param_valor_v1('UX.CLARITY_NODE_COUNT') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='UX' AND config_key='CLARITY_NODE_COUNT' AND hecho='as_clarity_node_count') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT UX.CLARITY_NODE_COUNT'; END IF;
 IF lf_ops.nucleo_param_valor_v1('UX.CLARITY_FOCUS_OUTLINE_PX') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='UX' AND config_key='CLARITY_FOCUS_OUTLINE_PX' AND hecho='as_focus_outline_px') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT UX.CLARITY_FOCUS_OUTLINE_PX'; END IF;
 IF lf_ops.nucleo_param_valor_v1('UX.CLARITY_FOCUS_OFFSET_PX') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='UX' AND config_key='CLARITY_FOCUS_OFFSET_PX' AND hecho='as_focus_offset_px') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT UX.CLARITY_FOCUS_OFFSET_PX'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22AS_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 h:=lf_ops.nucleo_hash_paquete_v1(cd,1); hashes:=hashes||jsonb_build_object(cd,h);
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22AS_VECTOR_FAIL %',cd; END IF; END LOOP;
 END LOOP;
 SELECT string_agg(j.key||'='||j.value,',' ORDER BY j.key) INTO hash_all FROM jsonb_each_text(hashes) j;
 RAISE EXCEPTION 'S22AS_HASH_ALL %',hash_all;
END $as$;
COMMIT;
